            <tr><td>The Salt Road</td><td>1</td><td>9</td></tr>
            <tr><td>A Year of Hedges</td><td>0</td><td>6</td></tr>
            <tr><td>Small Engines</td><td>2</td><td>7</td></tr>
            <tr><td>Notes from the Ferry</td><td>1</td><td>5</td></tr>
            <tr><td>The Glass Orchard</td><td>0</td><td>4</td></tr>
